 const load=useCallback(async()=>{try{const value=await api('state');setData(value);setLoadError('');return value;}catch(e:any){setLoadError(e.message);return null}},[]);
 useEffect(()=>{const l=localStorage.getItem('bv-lang');if(l==='en')setLang('en');const t=new URLSearchParams(location.search).get('invite');if(t){setInviteToken(t);if(signedIn)history.replaceState(null,'','/');}if(signedIn)load().then(v=>{if(v?.me?.role==='developer')setTab('overview')});},[load,signedIn]);
 useEffect(()=>{document.documentElement.lang=lang;document.documentElement.dir=ar?'rtl':'ltr';localStorage.setItem('bv-lang',lang)},[lang,ar]);
 const developer=data?.me?.role==='developer',manage=developer&&!preview;
 const allUnits:Row[]=data?.units||[],u=allUnits.find(x=>x.id===unitId)||allUnits[0],project=data?.projects?.find((x:Row)=>x.id===u?.project_id),unitRows=(key:string)=>(data?.[key]||[]).filter((x:Row)=>x.unit_id===u?.id);
 const balance=unitRows('payments').filter((x:Row)=>x.status==='approved').reduce((a:number,x:Row)=>a+x.amount,0);
 const bills=unitRows('installments').slice().sort((a:Row,b:Row)=>a.due.localeCompare(b.due));
 const paidBill=(id:string)=>unitRows('payments').filter((p:Row)=>p.installment_id===id&&p.status==='approved').reduce((a:number,p:Row)=>a+p.amount,0);
 const nextBill=bills.find((b:Row)=>paidBill(b.id)<b.amount);
 const fmt=(date:string)=>date?new Date(date).toLocaleDateString(ar?'ar-AE':'en-GB',{timeZone:'Asia/Dubai'}):'—';
 const fmtTime=(date:string)=>new Date(date).toLocaleString(ar?'ar-AE':'en-GB',{timeZone:'Asia/Dubai'});
 const status=(value:string)=><span className={'badge status-'+value}>{statuses[value]?.[ar?1:0]||value}</span>;
 const mutate=async(body:any)=>{setBusy(true);try{const r=await api('action',body);await load();toast.success(L('Saved','تم الحفظ'));return r;}catch(e){toast.error(msg(e));throw e;}finally{setBusy(false)}};
 const run=(body:any)=>{void mutate(body).catch(()=>{})};
