 const AddFile=({kind,id,unit=u?.id}:{kind:string;id?:string;unit?:string})=>preview?null:<button className="secondary" onClick={()=>setUpload({kind,targetId:id||'',unitId:unit||''})}><Upload size={16}/>{L('Add attachment','إضافة مرفق')}</button>;
 const requestEditor=()=>editor(L('New service request','طلب خدمة جديد'),[{key:'type',label:L('Request type','نوع الطلب'),type:'service',value:'general'},{key:'title',label:L('Subject','العنوان')},{key:'body',label:L('Request details','تفاصيل الطلب'),type:'textarea'}],'request.create',{unitId:u.id},'request');
