 const projectForm=()=>editor(L('Add project','إضافة مشروع'),[{key:'name',label:L('Project name','اسم المشروع')},{key:'location',label:L('Location','الموقع')},{key:'handover',label:L('Expected handover','التسليم المتوقع'),optional:true}],'project.create');
 const unitForm=()=>editor(L('Add apartment','إضافة شقة'),[{key:'projectId',label:L('Project','المشروع'),type:'select',options:(data?.projects||[]).map((p:Row)=>[p.id,p.name])},{key:'code',label:L('Unit number','رقم الشقة')},{key:'floor',label:L('Floor','الطابق')},{key:'bedrooms',label:L('Bedrooms','غرف النوم'),type:'number',value:2,min:0},{key:'area',label:L('Area (sq ft)','المساحة (قدم²)'),type:'number',min:1},{key:'price',label:L('Purchase price (AED)','سعر الشراء (درهم)'),type:'money',min:0.01},{key:'parking',label:L('Parking spaces','مواقف السيارات'),optional:true},{key:'dewa',label:L('DEWA account','حساب ديوا'),optional:true}],'unit.create');
 const buyerForm=()=>editor(L('Create buyer invitation','إنشاء دعوة مشتري'),[{key:'name',label:L('Full name','الاسم الكامل')},{key:'email',label:L('Email','البريد الإلكتروني'),type:'email'},{key:'phone',label:L('Phone','رقم الهاتف'),type:'tel',optional:true}],'buyer.create');
