 const unitSelector=allUnits.length>0?<Choice label={L('Select apartment','اختر الشقة')} value={u?.id||''} onChange={setUnitId} options={allUnits.map(x=>[x.id,`${data?.projects.find((p:Row)=>p.id===x.project_id)?.name} · ${x.code}`])}/>:null;
